import os


class Config:
    # =========================================================================
    # Directories and File Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_24"

    # Ensure working directory exists for caching
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Metadata Paths (Generated by previous steps)
    TRAIN_META = os.path.join(METADATA_DIR, "train.csv")
    VAL_META = os.path.join(METADATA_DIR, "validation.csv")
    TEST_META = os.path.join(METADATA_DIR, "test.csv")

    # Raw Data Paths
    TRACKING_TRAIN = os.path.join(INPUT_DIR, "train_player_tracking.csv")
    TRACKING_TEST = os.path.join(INPUT_DIR, "test_player_tracking.csv")
    HELMETS_TRAIN = os.path.join(INPUT_DIR, "train_baseline_helmets.csv")
    HELMETS_TEST = os.path.join(INPUT_DIR, "test_baseline_helmets.csv")

    # Output Paths
    SUBMISSION_PATH = "./submission/submission.csv"
    os.makedirs(os.path.dirname(SUBMISSION_PATH), exist_ok=True)

    # =========================================================================
    # Global Configuration
    # =========================================================================
    SEED = 42
    N_JOBS = 12

    # =========================================================================
    # Feature Engineering Configuration
    # =========================================================================

    # --- Stream A: Interaction Model (Translational + Visual) ---
    # Scope: Player-to-Player contacts (player2 != 'G')

    # Temporal Aggregation: Flattened Exponential Pyramids
    # Lags applied to System Energy features (Speed, Accel)
    # Captures convergence dynamics at multiple timescales
    STREAM_A_LAGS = [-15, -8, -4, -2, -1, 1, 2, 4, 8, 15]

    # Visual Consensus Lags (Sparse)
    # Used for IoU calculations to detect looming/occlusion
    STREAM_A_VISUAL_LAGS = [-15, -8, -4, 4, 8, 15]

    # Base features to expand with lags
    STREAM_A_LAG_COLS = ["speed", "acceleration"]

    # Final Feature List for Stream A
    # Includes Translational Differentials, System Energy (Current), and Visual Consensus
    # Note: Lagged columns (e.g., speed_p1_lag_1) will be auto-generated and appended
    STREAM_A_FEATURES = [
        "distance",  # Euclidean Distance
        "closure_rate",  # Finite Difference of Distance
        "speed_p1",
        "speed_p2",
        "acceleration_p1",
        "acceleration_p2",
        "max_iou",  # Visual Consensus: Max IoU across views
        "min_iou",  # Visual Consensus: Min IoU across views
        "iou_diff",  # Visual Uncertainty: |Sideline - Endzone|
        "visual_looming",  # Finite Difference of Max IoU
    ]

    # --- Stream B: Impact Model (Rotational + Invariant) ---
    # Scope: Player-to-Ground contacts (player2 == 'G')

    # Strict Invariance: Explicitly EXCLUDES x, y, direction, orientation, and visual features.
    # Focuses on inertial shock and loss of control.
    STREAM_B_FEATURES = [
        "ego_jerk_surge",  # Derivative of Projected Velocity (Surge)
        "ego_jerk_sway",  # Derivative of Projected Velocity (Sway)
        "speed",  # Invariant Scalar Baseline
        "acceleration",  # Invariant Scalar Baseline
    ]

    # =========================================================================
    # Model Hyperparameters (XGBoost)
    # =========================================================================

    # Sampling Strategy
    # Undersample negatives to maintain a manageable ratio while keeping all positives
    NEG_POS_RATIO = 10.0

    # Common XGBoost Parameters
    XGB_COMMON = {
        "booster": "gbtree",
        "tree_method": "gpu_hist",  # Utilizes NVIDIA A100
        "objective": "binary:logistic",
        "eval_metric": "logloss",
        "random_state": SEED,
        "n_jobs": N_JOBS,
    }

    # Stream A Parameters
    # Deeper trees (max_depth=6) to model complex interaction geometry and visual fusion
    XGB_STREAM_A = {
        **XGB_COMMON,
        "max_depth": 6,
        "learning_rate": 0.05,
        "subsample": 0.8,
        "colsample_bytree": 0.8,
        "n_estimators": 5000,  # Controlled by Early Stopping
    }

    # Stream B Parameters
    # Shallow trees (max_depth=6) to prevent overfitting sensor noise, relying on robust Jerk signals
    XGB_STREAM_B = {
        **XGB_COMMON,
        "max_depth": 6,
        "learning_rate": 0.05,
        "subsample": 0.8,
        "colsample_bytree": 0.8,
        "n_estimators": 5000,  # Controlled by Early Stopping
    }

    # Training Loop Control
    EARLY_STOPPING_ROUNDS = 50
    VERBOSE_EVAL = 50

    # Inference Threshold Optimization
    # Default starting point, will be optimized via linear search on Validation set
    DEFAULT_THRESHOLD = 0.5
